accuracyData = {
  const [wLo, wHi] = analysis_window;
  const perTrial = [];
  for (const r of groupedRows) {
    let t = r.t0, n = 0, p = 0;
    for (const [aoi, len] of r.runs) {
      for (let k = 0; k &lt; len; k++, t += STEP_MS) {
        if (t &lt; wLo || t &gt; wHi || aoi &gt; 1) continue;
        n += 1;
        if (aoi === 0) p += 1;
      }
    }
    if (n &gt; 0) perTrial.push({ age_bin: r.age_bin, word: r.word, prop: p / n });
  }
  const groups = d3.group(perTrial, (d) =&gt; d.age_bin, (d) =&gt; d.word);
  const out = [];
  for (const [bin, byWord] of groups) {
    for (const [word, rows] of byWord) {
      const mean = d3.mean(rows, (d) =&gt; d.prop);
      const sem = (d3.deviation(rows, (d) =&gt; d.prop) || 0) / Math.sqrt(rows.length);
      out.push({
        age_bin: bin, word, n_trials: rows.length, mean,
        ci_lower: mean - 1.96 * sem, ci_upper: mean + 1.96 * sem,
      });
    }
  }
  return out.sort((a, b) =&gt; d3.ascending(a.age_bin, b.age_bin));
}







