rtData = {
  const out = [];
  for (const r of groupedRows) {
    const res = trialRT(r.t0, r.runs);
    if (res && res.rt != null) {
      out.push({
        age_bin: r.age_bin, word: r.word, rt: res.rt,
        shift_type: res.shift_type, dataset: r.dataset,
      });
    }
  }
  return out;
}

rtMeans = {
  const dt = rtData.filter((d) =&gt; d.shift_type === "D-T");
  const out = [];
  for (const [bin, byWord] of d3.group(dt, (d) =&gt; d.age_bin, (d) =&gt; d.word)) {
    for (const [word, rows] of byWord) {
      const mean = d3.mean(rows, (d) =&gt; d.rt);
      const sem = (d3.deviation(rows, (d) =&gt; d.rt) || 0) / Math.sqrt(rows.length);
      out.push({
        age_bin: bin, word, n_trials: rows.length, mean_rt: mean,
        ci_lower: mean - 1.96 * sem, ci_upper: mean + 1.96 * sem,
      });
    }
  }
  return out.sort((a, b) =&gt; d3.ascending(a.age_bin, b.age_bin));
}
















